function RESIDUE-DEGREE(a, m):
    require gcd(a mod m, m) = 1              # a must be a unit
    x <- a mod m
    for k = 1, 2, 3, ... , m:
        if x = 1 mod m or x = m - 1 mod m:
            return k                          # least signed order
        x <- (x * a) mod m
    error 'unreachable for a unit'

function CARMICHAEL-BOUND(m):
    e <- 1
    for each unit a modulo m:
        k <- multiplicative order of a modulo m
        e <- lcm(e, k)
    return e                                  # exponent of the unit group

function TYPE-CENSUS(m):
    census <- empty map
    for a = 0 .. m-1 with gcd(a, m) = 1:
        d <- RESIDUE-DEGREE(a, m)
        census[d] <- census[d] + 1
    return census

function ORDER-PROFILE(n_1, ..., n_r):
    profile <- empty map
    for each (x_1, ..., x_r) in Z/n_1 x ... x Z/n_r:
        d <- lcm over i of (n_i / gcd(x_i, n_i))
        profile[d] <- profile[d] + 1
    return profile

function CHEBOTAREV-RECONCILIATION(m, n_1, ..., n_r):
    census  <- TYPE-CENSUS(m)
    profile <- ORDER-PROFILE(n_1, ..., n_r)
    return for every d:  census[d] = 2 * profile[d]

function FROBENIUS-ORBITS(g, (n_1, ..., n_r)):
    seen <- empty set;  orbits <- empty list
    for each x in the group:
        if x in seen: continue
        orbit <- empty list;  y <- x
        while y not in seen:
            insert y into seen;  append y to orbit
            y <- y + g                      # coordinatewise, modulo each n_i
        append orbit to orbits
    return orbits

function SPLITTING-SHAPE(g, factors):
    orbits <- FROBENIUS-ORBITS(g, factors)
    f <- ord(g) = lcm over i of (n_i / gcd(g_i, n_i))
    assert every orbit has length f          # orbit purity
    assert f * |orbits| = |A|                # the e*f*g law with e = 1
    return (f, |orbits|)

function ABELIAN-GROUPS(n):
    groups <- [ [] ]
    for each prime power p^e || n:
        groups <- { g ++ [p^k : k in part] : g in groups, part in partitions(e) }
    return groups

function PROFILE-ENTROPY(factors):
    profile <- ORDER-PROFILE(factors);  N <- sum of profile
    return - sum over d of (profile[d]/N) * log2(profile[d]/N)

function IDENTIFY-GROUP(n, H_measured, tol):
    matches <- empty list
    for each A in ABELIAN-GROUPS(n):
        if |PROFILE-ENTROPY(A) - H_measured| < tol:
            append INVARIANT-FACTOR-NAME(A) to matches
    return matches          # a single entry means the group is determined

