function ANALYSE-CONDUCTOR(f):
    U <- { a in [0, f) : gcd(a, f) = 1 }
    degree   <- |{ min(a, f - a) : a in U }|          # the +- classes
    exponent <- lcm over a in U of RESIDUE-DEGREE(a, f)
    cyclic   <- (exponent = degree)
    return (f, |U|, degree, exponent, cyclic)

function SELECT-FIRST-NONCYCLIC(n):
    for f = 3, 4, 5, ... while phi(f) <= 2n or f <= bound:
        if phi(f) = 2n:
            record <- ANALYSE-CONDUCTOR(f)
            if not record.cyclic: return f
    return none

